    "81dfc5d4": {"text":"Bearbeite die Bänke.","hash":"h1-14453f81"},
    "81ffb7ef": {"text":"sie sind miteinander verheiratet.","hash":"h1-ee6c47e9"},
    "82045fbc": {"text":"Kämpfe um dein Leben.","hash":"h1-65eab321"},
    "8204bb81": {"text":"📜 Zeugen und Tinte belegen Ihren Anspruch auf {province}.","hash":"h1-c130ed17"},
